table:
CREATE TABLE customers (
    customer_id TEXT PRIMARY KEY,
    email TEXT UNIQUE,
    signup_date DATE
);

CREATE TABLE orders (
    order_id TEXT PRIMARY KEY,
    customer_id TEXT,
    order_date DATE,
    status TEXT,
    FOREIGN KEY(customer_id) REFERENCES customers(customer_id)
);

CREATE TABLE suppliers (
    supplier_id TEXT PRIMARY KEY,
    name TEXT NOT NULL,
    country TEXT
);

CREATE TABLE products (
    product_id TEXT PRIMARY KEY,
    name TEXT NOT NULL,
    supplier_id TEXT,
    category TEXT,
    FOREIGN KEY(supplier_id) REFERENCES suppliers(supplier_id)
);

CREATE TABLE customers (
    customer_id TEXT PRIMARY KEY,
    first_name TEXT,
    last_name TEXT,
    country TEXT
);

CREATE TABLE orders (
    order_id TEXT PRIMARY KEY,
    customer_id TEXT,
    order_date DATE,
    total_amount REAL,
    FOREIGN KEY(customer_id) REFERENCES customers(customer_id)
);

CREATE TABLE products (
    product_id TEXT PRIMARY KEY,
    product_name TEXT,
    category TEXT
);

CREATE TABLE returns (
    return_id TEXT PRIMARY KEY,
    product_id TEXT,
    return_date DATE,
    return_value DECIMAL(10, 2),
    FOREIGN KEY(product_id) REFERENCES products(product_id)
);

/* Sample return: ('ret_xyz', 'prod_123', '2023-10-25', 650.00) */

CREATE TABLE products (
    product_id TEXT PRIMARY KEY,
    product_name TEXT,
    brand_name TEXT,
    category TEXT /* e.g., 'Footwear', 'footwear', 'shoes' */
);

CREATE TABLE order_items (
    item_id TEXT PRIMARY KEY,
    order_id TEXT,
    product_id TEXT,
    quantity INTEGER
);

/* Note: product_id in order_items corresponds to product_id in products */

CREATE TABLE suppliers (
    supplier_id TEXT PRIMARY KEY,
    supplier_name TEXT NOT NULL
);

CREATE TABLE returns (
    return_id TEXT PRIMARY KEY,
    supplier_id TEXT,
    return_value DECIMAL(10, 2),
    FOREIGN KEY(supplier_id) REFERENCES suppliers(supplier_id)
);

/*
Note: The returns table may not contain entries for every supplier.
Some suppliers might have zero returns recorded.
*/

CREATE TABLE posts (
    post_id TEXT PRIMARY KEY,
    campaign_id TEXT,
    post_text TEXT,
    likes INTEGER,
    comments INTEGER,
    shares INTEGER,
    FOREIGN KEY(campaign_id) REFERENCES campaigns(campaign_id)
);

CREATE TABLE campaigns (
    campaign_id TEXT PRIMARY KEY,
    campaign_name TEXT
);

/* 
campaign_name values in the campaigns table have inconsistent casing, e.g., 'SummerSale', 'summersale', 'Summer Sale 24' 
*/
